namespace rawrxd::next15 {
CounterView read(const Counters& c){return {c.pipeline_creates.load(),c.gpu_submits.load(),c.gpu_gemv.load(),c.gpu_gemm.load(),c.gpu_layers.load(),c.cpu_fallbacks.load(),c.strict_violations.load(),c.host_upload_bytes.load(),c.residency_hits.load(),c.residency_misses.load(),c.generated_tokens.load()};}
Result certify_gpu(const CounterView& b,const CounterView& a,bool numeric_ok){
 if(!numeric_ok)return Result::fail("non-finite or reference-mismatched GPU output");
 if(a.gpu_submits<=b.gpu_submits || (a.gpu_gemv<=b.gpu_gemv && a.gpu_gemm<=b.gpu_gemm) || a.gpu_layers<=b.gpu_layers)return Result::fail("no demonstrated executed forward GPU dispatch");
 if(a.cpu_fallbacks!=b.cpu_fallbacks || a.strict_violations!=b.strict_violations)return Result::fail("unexpected fallback or GPU violation");
 return Result::ok("GPU forward execution and numerical parity observed");}
void Profiler::record(std::string_view stage,std::uint64_t ns,std::uint64_t bytes){std::lock_guard lk(mu_); auto& s=stages_[std::string(stage)];++s.calls;s.nanoseconds+=ns;s.bytes+=bytes;}
std::map<std::string,Stage> Profiler::snapshot(){std::lock_guard lk(mu_);return stages_;}
Scope::~Scope(){auto ns=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start_).count();p_->record(stage_,ns<0?0:static_cast<std::uint64_t>(ns),bytes_);}
std::optional<FiniteFailure> first_nonfinite(std::span<const float> v){for(std::size_t i=0;i<v.size();++i)if(!std::isfinite(v[i]))return FiniteFailure{i,v[i]};return {};}
Result compare(std::span<const float> x,std::span<const float> y,float atol,float rtol){if(x.size()!=y.size())return Result::fail("reference size mismatch");if(atol<0||rtol<0)return Result::fail("invalid tolerance");for(std::size_t i=0;i<x.size();++i){if(!std::isfinite(x[i])||!std::isfinite(y[i]))return Result::fail("non-finite at index "+std::to_string(i));if(std::abs(x[i]-y[i])>atol+rtol*std::abs(x[i]))return Result::fail("numeric mismatch at index "+std::to_string(i));}return Result::ok();}
float half_to_float(std::uint16_t h){const std::uint32_t sign=(std::uint32_t(h&0x8000u))<<16;std::uint32_t exp=(h>>10)&31u;std::uint32_t mant=h&1023u;std::uint32_t f;if(exp==0){if(mant==0)f=sign;else{int e=-14;while((mant&1024u)==0){mant<<=1;--e;}mant&=1023u;f=sign|(std::uint32_t(e+127)<<23)|(mant<<13);}}else if(exp==31)f=sign|0x7f800000u|(mant<<13);else f=sign|((exp+112u)<<23)|(mant<<13);return std::bit_cast<float>(f);}
Result q8_0_dot(std::span<const std::byte> p,std::span<const float> rhs,float& out){out=0;if(rhs.empty()||rhs.size()%32!=0||p.size()!=rhs.size()/32*34)return Result::fail("Q8_0 block geometry invalid");double sum=0;for(std::size_t block=0;block<rhs.size()/32;++block){const std::size_t o=block*34;const std::uint16_t h=std::to_integer<std::uint16_t>(p[o])|(std::to_integer<std::uint16_t>(p[o+1])<<8);float d=half_to_float(h);if(!std::isfinite(d))return Result::fail("nonfinite block scale");for(std::size_t j=0;j<32;++j){const auto bits=std::to_integer<std::uint8_t>(p[o+2+j]);const std::int8_t q=std::bit_cast<std::int8_t>(bits);if(!std::isfinite(rhs[block*32+j]))return Result::fail("nonfinite RHS");sum+=double(d)*q*rhs[block*32+j];}}out=static_cast<float>(sum);return std::isfinite(out)?Result::ok():Result::fail("nonfinite Q8 output");}
Result audit_fences(std::span<const FenceTrace> t,std::vector<std::uint64_t>& candidates){candidates.clear();std::uint64_t last=0;for(auto& f:t){if(f.submit_id==0 || f.submit_id<=last)return Result::fail("submit IDs must be nonzero, strictly increasing");last=f.submit_id;if(f.waited_for_submit>=f.submit_id && f.waited_for_submit!=0)return Result::fail("invalid forward/self dependency");if(f.wait_ns>0&&!f.dependency_confirmed)candidates.push_back(f.submit_id);}return Result::ok("flagged "+std::to_string(candidates.size())+" waits for manual dependency validation");}
bool ResidencyBudget::try_reserve(std::uint64_t n){if(reserved>capacity||n>capacity-reserved)return false;reserved+=n;return true;}void ResidencyBudget::release(std::uint64_t n){reserved=n>reserved?0:reserved-n;}
Result validate_placement(std::span<const Placement> p,std::span<const std::uint64_t> budgets){std::vector<std::uint64_t> use(budgets.size());for(const auto& x:p){if(x.gpu>=budgets.size()||!std::isfinite(x.estimated_work)||x.estimated_work<0)return Result::fail("invalid GPU assignment");if(x.bytes>budgets[x.gpu]-std::min(use[x.gpu],budgets[x.gpu]))return Result::fail("GPU memory budget exceeded");use[x.gpu]+=x.bytes;}return Result::ok();}
std::vector<ExpertHit> top_experts(std::span<const std::uint32_t> ids,std::size_t k){std::map<std::uint32_t,std::uint64_t> counts;for(auto id:ids)++counts[id];std::vector<ExpertHit> out;for(auto [id,n]:counts)out.push_back({id,n});std::sort(out.begin(),out.end(),[](auto a,auto b){return a.count!=b.count?a.count>b.count:a.expert<b.expert;});if(out.size()>k)out.resize(k);return out;}
GreedyDraft verify_greedy(std::span<const float> logits,std::uint32_t token){if(logits.empty()||token>=logits.size()||first_nonfinite(logits))return {token,false};auto best=std::max_element(logits.begin(),logits.end());return {token,static_cast<std::size_t>(best-logits.begin())==token};}
std::uint64_t max_context(const ContextBudget& b){if(b.kv_bytes_per_token==0 || b.weights_bytes>b.memory_budget || b.other_bytes>b.memory_budget-b.weights_bytes)return 0;return (b.memory_budget-b.weights_bytes-b.other_bytes)/b.kv_bytes_per_token;}
static double median(std::vector<double> v){std::sort(v.begin(),v.end());std::size_t n=v.size();return n%2?v[n/2]:(v[n/2-1]+v[n/2])*0.5;}
Result promote(std::span<const PerformanceSample> b,std::span<const PerformanceSample> c,const PromotionRule& r){if(b.size()<3||c.size()<3)return Result::fail("minimum three baseline and three candidate samples required");if(r.minimum_gain_pct<0||r.maximum_latency_regression_pct<0)return Result::fail("invalid promotion rules");std::vector<double> bv,cv,bl,cl;for(auto [samples,tps,lat]:{std::tuple{b,&bv,&bl},std::tuple{c,&cv,&cl}}){for(const auto& s:samples){if(!s.correct||s.fallback||!std::isfinite(s.decode_tps)||s.decode_tps<=0||!std::isfinite(s.p95_ms)||s.p95_ms<=0)return Result::fail("incorrect/fallback/nonfinite samples");if(r.maximum_peak_bytes && s.peak_bytes>r.maximum_peak_bytes)return Result::fail("peak memory limit exceeded");tps->push_back(s.decode_tps);lat->push_back(s.p95_ms);}}double bt=median(bv),ct=median(cv),bp=median(bl),cp=median(cl);if(ct<bt*(1.0+r.minimum_gain_pct/100.0))return Result::fail("candidate has insufficient median decode TPS gain");if(cp>bp*(1+r.maximum_latency_regression_pct/100.0))return Result::fail("p95 latency regression exceeds limit");return Result::ok("eligible for review; repeat independent validation before promotion");}
std::optional<Profile> choose_profile(std::span<const Profile> profiles,std::string_view model,std::string_view device,std::string_view quant){std::optional<Profile> best;for(auto& p:profiles)if(p.certified&&p.model_hash==model&&p.device_id==device&&p.quant==quant&&std::isfinite(p.measured_tps)&&p.measured_tps>0&&(!best||p.measured_tps>best->measured_tps))best=p;return best;}
Result certify_gateway(const GatewayProbe& p){if(p.health&&p.models&&p.chat&&p.stream&&p.cancel&&p.agent&&p.snapshots&&p.ollama&&p.deep2&&p.coexist&&p.ide&&p.ghost)return Result::ok();return Result::fail("gateway feature certification incomplete; each probe must be actually executed");}
std::string json_escape(std::string_view s){std::string out;out.reserve(s.size()+8);for(unsigned char ch:s){switch(ch){case '"':out+="\\\"";break;case '\\':out+="\\\\";break;case '\n':out+="\\n";break;case '\r':out+="\\r";break;case '\t':out+="\\t";break;default:if(ch<0x20){char buf[7];std::snprintf(buf,sizeof(buf),"\\u%04x",unsigned(ch));out+=buf;}else out+=char(ch);}}return out;}
Result write_receipt(const std::filesystem::path& path,const RunConfig& cfg,const CounterView& c,const std::map<std::string,Stage>& stages,const std::map<std::string,Result>& gates){std::ofstream out(path,std::ios::binary|std::ios::trunc);if(!out)return Result::fail("cannot open receipt file");auto str=[&](std::string_view s){out<<'"'<<json_escape(s)<<'"';};out<<"{\n  \"schema\": \"RAWRXD_NEXT15_007\",\n  \"config\": {\"model\":";str(cfg.model);out<<",\"model_hash\":";str(cfg.model_hash);out<<",\"git_revision\":";str(cfg.git_revision);out<<",\"quant\":";str(cfg.quant);out<<",\"backend\":";str(cfg.backend);out<<",\"context\":"<<cfg.context<<",\"gpu_index\":"<<cfg.gpu_index<<"},\n  \"counters\": {\"gpu_submits\":"<<c.gpu_submits<<",\"gpu_gemv\":"<<c.gpu_gemv<<",\"gpu_gemm\":"<<c.gpu_gemm<<",\"gpu_layers\":"<<c.gpu_layers<<",\"cpu_fallbacks\":"<<c.cpu_fallbacks<<",\"strict_violations\":"<<c.strict_violations<<",\"upload_bytes\":"<<c.host_upload_bytes<<",\"generated_tokens\":"<<c.generated_tokens<<"},\n  \"stages\": {";bool first=true;for(auto& [name,s]:stages){if(!first)out<<',';first=false;str(name);out<<":{\"calls\":"<<s.calls<<",\"ns\":"<<s.nanoseconds<<",\"bytes\":"<<s.bytes<<'}';}out<<"},\n  \"gates\": {";first=true;for(auto& [name,r]:gates){if(!first)out<<',';first=false;str(name);out<<":{\"pass\":"<<(r.pass?"true":"false")<<",\"message\":";str(r.message);out<<'}';}out<<"}\n}\n";out.flush();return out?Result::ok():Result::fail("receipt write failed");}
void on_gpu_submit(Counters& c,std::uint64_t bytes){++c.gpu_submits;c.host_upload_bytes+=bytes;}void on_gpu_kernel(Counters& c,bool gemm){if(gemm)++c.gpu_gemm;else ++c.gpu_gemv;}void on_gpu_layer_complete(Counters& c){++c.gpu_layers;}void on_cpu_fallback(Counters& c){++c.cpu_fallbacks;}
}
